"package com.example.educationpath.ui.viewmodel\n\nimport androidx.lifecycle.SavedStateHandle\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport com.example.educationpath.data.model.Step\nimport com.example.educationpath.repository.EducationRepository\nimport dagger.hilt.android.lifecycle.SavedStateViewModel\import kotlinx.coroutines.flow.SharingStarted\import kotlinx.coroutines.flow.StateFlow\import kotlinx.coroutines.flow.combine\import kotlinx.coroutines.flow.map\import kotlinx.coroutines.flow.stateIn\import javax.inject.Inject\n\n@SavedStateViewModel\nclass PathDetailViewModel @Inject constructor(\n    private val repository: EducationRepository,\n    savedStateHandle: SavedStateHandle\n) : ViewModel() {\n\n    // Assume pathId is passed via savedStateHandle\n    val pathId: Long = savedStateHandle.get(\"pathId\") ?: throw IllegalArgumentException(\"Path ID required\")\n\n    val steps: StateFlow<List<Step>> = repository.getStepsForPath(pathId)\n        .stateIn(\n            scope = viewModelScope,\n            started = SharingStarted.WhileSubscribed(5000),\n            initialValue = emptyList()\n        )\n    \n    fun toggleStepCompletion(stepId: Long) { \n        // Logic to fetch current state, toggle boolean, and call repository.updateStep()\n    }\n\n    fun isPathCompleted(): Boolean { \n        // Logic to check if all steps in the observed list are complete\n        return steps.value.all { it.isCompleted }\n    }\n}"